<script setup lang="ts">
import {computed,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {ArrowLeftOutlined,PlusOutlined,EyeOutlined,EditOutlined} from '@ant-design/icons-vue'
import {api,errorMessage,idempotencyKey,type Page,type Permission,type Role} from '../../api/http'
import {useAuthStore} from '../../stores/auth'
import {descendants,type MenuEntry} from './menuCatalog'
import {isOrdinaryPermission,permissionChanges} from './menuConfigurationModel'
import './menuConfiguration.css'
const route=useRoute(),router=useRouter(),auth=useAuthStore()
const creating=computed(()=>route.meta.mode==='create'),readonly=computed(()=>route.meta.mode==='view')
const empty=():MenuEntry=>({id:'',menuCode:'',menuName:'',routePath:'',parentId:null,sortNo:100,status:'ACTIVE',version:0,permissionCode:null,requiredPermissions:null,permissionCodes:[]})
const menu=reactive(empty()),menus=ref<MenuEntry[]>([]),catalog=ref<Permission[]>([]),original=ref<Permission[]>([]),roles=ref<Role[]>([])
const nodeType=ref<'MENU'|'DIRECTORY'>('MENU'),activeTab=ref('special'),loading=ref(false),busy=ref(false),error=ref(''),message=ref(''),roleError=ref(''),readFailed=ref(false),bindings=ref<string[]>([])
const copy=<T,>(x:T):T=>JSON.parse(JSON.stringify(x)) as T
const canEdit=computed(()=>!readonly.value&&auth.can(creating.value?'iam:menu:create':'iam:menu:update')&&auth.can('iam:permission:view')&&!loading.value&&!busy.value&&!readFailed.value)
const state=()=>JSON.stringify([menu,nodeType.value,catalog.value,bindings.value])
const initial=ref(''),dirty=computed(()=>initial.value!==''&&state()!==initial.value)
async function all<T>(url:string){const result:T[]=[];for(let page=0;;page++){const data=await api<Page<T>>({url,params:{page,size:100}});result.push(...data.items);if(result.length>=data.total)return result;if(!data.items.length)throw Error('Incomplete catalog')}}
async function load(){loading.value=true;readFailed.value=false;error.value='';initial.value='';try{menus.value=await all<MenuEntry>('/menus');Object.assign(menu,creating.value?empty():await api<MenuEntry>({url:`/menus/${route.params.id}`}));nodeType.value=menu.routePath===null?'DIRECTORY':'MENU';if(auth.can('iam:permission:view'))catalog.value=await all<Permission>('/permissions');else{catalog.value=[];error.value='没有读取权限目录的权限，当前配置不可保存。'}original.value=copy(catalog.value);bindings.value=[...(menu.permissionCodes??[])];if(menu.permissionCode&&!bindings.value.includes(menu.permissionCode))bindings.value.push(menu.permissionCode);initial.value=state();roles.value=[];roleError.value='';if(!creating.value&&auth.can('iam:role:view'))try{roles.value=(await all<Role>('/roles')).filter(r=>r.menuCodes.includes(menu.menuCode))}catch(cause){roleError.value=errorMessage(cause)}else if(!creating.value)roleError.value='没有读取关联角色的权限。'}catch(cause){readFailed.value=true;error.value=errorMessage(cause)}finally{loading.value=false}}
const specialList=computed(()=>catalog.value.filter(p=>bindings.value.includes(p.permissionCode)&&!isOrdinaryPermission(p,menu.permissionCode)))
const available=computed(()=>catalog.value.filter(p=>p.status==='ACTIVE'&&!bindings.value.includes(p.permissionCode)&&!isOrdinaryPermission(p,menu.permissionCode)).map(p=>({value:p.permissionCode,label:`${p.permissionName} (${p.permissionCode})`})))
const parents=computed(()=>{const excluded=new Set(menu.id?descendants(menu.id,menus.value).map(m=>m.id):[]);return menus.value.filter(m=>m.routePath===null&&!excluded.has(m.id)).map(m=>({value:m.id,label:m.menuName}))})
function routePermission(){if(nodeType.value==='DIRECTORY')return null;const resolved=router.resolve(menu.routePath||'');if(!resolved.matched.length||resolved.matched.some(r=>r.path.includes(':pathMatch')))throw Error('页面地址未关联到已有业务页面');const code=resolved.meta.permission;if(menu.routePath==='/'&&!code)return 'menu:home';if(typeof code!=='string')throw Error('页面未定义既有查看权限');if(!catalog.value.some(p=>p.permissionCode===code&&p.status==='ACTIVE'))throw Error('页面查看权限不存在或已停用');return code}
async function save(){if(!canEdit.value)return;error.value='';message.value='';if(!menu.menuName.trim()||!menu.menuCode.trim()){error.value='菜单名称和菜单编码必填';return}if(nodeType.value==='MENU'&&(!menu.routePath?.startsWith('/')||menu.routePath.startsWith('//'))){error.value='页面地址必须以 / 开头';return}try{const permissionCode=routePermission();const preserve=menu.permissionCode===permissionCode;const ordinary=preserve?[]:catalog.value.filter(p=>isOrdinaryPermission(p,permissionCode)&&p.permissionCode.split(':').slice(0,2).join(':')===permissionCode?.split(':').slice(0,2).join(':')&&p.status==='ACTIVE').map(p=>p.permissionCode);const codes=nodeType.value==='DIRECTORY'?[]:[...new Set([...bindings.value,...ordinary,permissionCode!])];const data={menu:{...menu,menuName:menu.menuName.trim(),routePath:nodeType.value==='DIRECTORY'?null:menu.routePath,permissionCode,requiredPermissions:nodeType.value==='DIRECTORY'?null:preserve?menu.requiredPermissions:(router.resolve(menu.routePath||'').meta.requiredPermissions as string[]|undefined)?.join(',')??null,reason:'菜单配置维护（系统记录）'},permissionCodes:codes,permissionChanges:permissionChanges(catalog.value,original.value,codes)};busy.value=true;const saved=await api<MenuEntry>({method:creating.value?'POST':'PUT',url:creating.value?'/menus/configuration':`/menus/${menu.id}/configuration`,headers:{'Idempotency-Key':idempotencyKey(),...(!creating.value?{'If-Match':`"${menu.version}"`}:{})},data});Object.assign(menu,saved);bindings.value=codes;original.value=copy(catalog.value);initial.value=state();window.dispatchEvent(new Event('mes-navigation-changed'));busy.value=false;if(creating.value)await router.replace(`/admin/menus/${saved.id}/edit`);await load();message.value='菜单配置已保存'}catch(cause){error.value=cause instanceof Error&&!('isAxiosError' in cause)?cause.message:errorMessage(cause)}finally{busy.value=false}}
function confirmLeave(){return !busy.value&&(!dirty.value||window.confirm('离开将放弃未保存的菜单配置，是否继续？'))}
function back(){if(confirmLeave()){initial.value=state();router.push({path:'/admin/menus',query:route.query})}}
function restore(){if(!dirty.value||window.confirm('恢复上次保存将放弃当前修改，是否继续？'))load()}
onBeforeRouteLeave(confirmLeave);onBeforeRouteUpdate(confirmLeave)
const unload=(event:BeforeUnloadEvent)=>{if(dirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
watch(()=>route.fullPath,()=>{activeTab.value='special';load()},{immediate:true})
const modal=ref(false),mode=ref<'new'|'edit'|'link'>('new'),form=reactive({code:'',name:'',description:'',status:'ACTIVE'}),formError=ref('')
function openModal(value:'new'|'edit'|'link',permission?:Permission){if(!canEdit.value)return;mode.value=value;Object.assign(form,{code:permission?.permissionCode??'',name:permission?.permissionName??'',description:permission?.description??'',status:permission?.status??'ACTIVE'});formError.value='';modal.value=true}
function submit(){formError.value='';if(!canEdit.value)return;if(mode.value==='link'){if(!available.value.some(p=>p.value===form.code)){formError.value='请选择已有特殊权限';return}bindings.value.push(form.code);modal.value=false;return}if(!form.name.trim()||!form.code.trim()){formError.value='权限名称和编码必填';return}if(!/^[a-z][a-z0-9-]*(?::[a-z][a-z0-9-]*){2}$/.test(form.code)){formError.value='权限编码必须为小写三段格式';return}const old=catalog.value.find(p=>p.permissionCode===form.code);if(mode.value==='new'&&old){formError.value='权限编码已存在，请关联已有权限';return}const candidate:Permission={id:old?.id??'',version:old?.version??0,permissionCode:form.code,permissionName:form.name.trim(),description:form.description,permissionType:old?.permissionType??'ACTION',routePath:old?.routePath,status:form.status};if(isOrdinaryPermission(candidate,menu.permissionCode)){formError.value='固定普通权限不可作为特殊权限配置';return}if(old)Object.assign(old,candidate);else{catalog.value.push(candidate);bindings.value.push(form.code)}modal.value=false}
function unlink(p:Permission){if(canEdit.value&&window.confirm('解除菜单关联？权限定义和已有角色授权不会删除。'))bindings.value=bindings.value.filter(code=>code!==p.permissionCode)}
const specialRole=(role:Role)=>specialList.value.filter(p=>role.permissionCodes.includes(p.permissionCode)).map(p=>p.permissionName)
const level=(role:Role)=>catalog.value.some(p=>bindings.value.includes(p.permissionCode)&&isOrdinaryPermission(p,menu.permissionCode)&&p.permissionCode!==menu.permissionCode&&!p.permissionCode.endsWith(':view')&&role.permissionCodes.includes(p.permissionCode))?'管理':'只查看'
const roleInfo=ref<Role|null>(null)
</script>
<template><main :data-ui-template="readonly?'T3':'T2'" class="menu-prototype">
<header class="menu-page-title"><a-button aria-label="返回" :disabled="busy" @click="back"><ArrowLeftOutlined aria-hidden="true"/>返回</a-button><h1>{{readonly?'菜单详情':creating?'新增菜单':'菜单编辑与功能权限配置'}}</h1><span v-if="dirty" class="menu-unsaved">有未保存的修改</span></header>
<a-alert v-if="error" type="error" :message="error" show-icon/><a-alert v-if="message" type="success" :message="message" show-icon/>
<a-spin :spinning="loading"><section class="menu-panel menu-info"><h2>菜单信息</h2><div class="menu-fields">
<label class="menu-pair"><span class="form-field-label">菜单名称 <em>*</em></span><a-input aria-label="菜单名称" v-model:value="menu.menuName" :disabled="!canEdit" :maxlength="100"/></label>
<label class="menu-pair"><span class="form-field-label">菜单编码</span><a-input aria-label="菜单编码" v-model:value="menu.menuCode" :disabled="!creating||!canEdit" :maxlength="64"/></label>
<label class="menu-pair"><span class="form-field-label">上级菜单</span><a-select aria-label="上级菜单" v-model:value="menu.parentId" :disabled="!canEdit" :options="parents" allow-clear show-search option-filter-prop="label"/></label>
<label v-if="nodeType==='MENU'" class="menu-pair"><span class="form-field-label">页面地址 <em>*</em></span><a-input aria-label="页面地址" v-model:value="menu.routePath" :disabled="!canEdit" :maxlength="255"/></label>
<div class="menu-pair"><span>菜单类型</span><a-radio-group aria-label="菜单类型" v-model:value="nodeType" :disabled="!canEdit"><a-radio value="MENU">页面菜单</a-radio><a-radio value="DIRECTORY">目录</a-radio></a-radio-group></div>
<div class="menu-pair"><span>状态</span><a-radio-group aria-label="菜单状态" v-model:value="menu.status" :disabled="!canEdit"><a-radio value="ACTIVE">启用</a-radio><a-radio value="INACTIVE">停用</a-radio></a-radio-group></div>
<label class="menu-pair"><span class="form-field-label">排序</span><a-input-number aria-label="排序" v-model:value="menu.sortNo" :disabled="!canEdit" :min="0" :precision="0"/></label>
</div></section>
<section class="menu-panel menu-ordinary"><div class="menu-ordinary-heading"><h2>普通权限（系统固定）</h2><span>只查看／管理由角色授权选择，此处不可修改等级</span></div><div class="menu-ordinary-cards"><div class="menu-ordinary-card"><EyeOutlined class="menu-ordinary-icon"/><div><strong>只查看</strong><p>允许查询、查看详情等只读操作。</p></div></div><div class="menu-ordinary-card"><EditOutlined class="menu-ordinary-icon"/><div><strong>管理</strong><p>包含查看、新增、修改、业务允许的删除，以及未单独配置特殊权限的打印、导出等普通操作。</p></div></div></div></section>
<section class="menu-panel menu-tabs"><div class="menu-tab-line"><div class="menu-tab-buttons"><button :class="{active:activeTab==='special'}" @click="activeTab='special'">特殊权限配置</button><button :class="{active:activeTab==='roles'}" :disabled="creating" @click="activeTab='roles'">关联角色</button></div><div v-if="activeTab==='special'&&nodeType==='MENU'&&canEdit" class="menu-tab-actions"><a-button @click="openModal('link')">关联已有权限</a-button><a-button v-if="auth.can('iam:permission:create')" type="primary" @click="openModal('new')"><PlusOutlined aria-hidden="true"/>新增特殊权限</a-button></div></div>
<template v-if="activeTab==='special'"><p class="menu-hint">特殊权限需由角色独立授权，普通管理权限不会自动获得审核、电子签名、放行等受控操作。</p><div v-if="nodeType==='MENU'" class="menu-table-scroll"><table class="menu-special-table"><thead><tr><th>序号</th><th>权限名称</th><th>权限编码</th><th>说明</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="(p,index) in specialList" :key="p.permissionCode"><td>{{index+1}}</td><td>{{p.permissionName}}</td><td>{{p.permissionCode}}</td><td class="muted">{{p.description||'—'}}</td><td><span :class="p.status==='ACTIVE'?'menu-green':'menu-gray'">{{p.status==='ACTIVE'?'● 启用':'● 停用'}}</span></td><td><a-button v-if="canEdit&&auth.can('iam:permission:update')" type="link" aria-label="编辑特殊权限" @click="openModal('edit',p)">编辑</a-button><a-button v-if="canEdit" type="link" @click="unlink(p)">解除关联</a-button></td></tr></tbody></table><a-empty v-if="!specialList.length" description="尚未关联特殊权限"/></div><a-empty v-else description="目录不配置功能权限"/></template>
<template v-else><p class="menu-hint">仅查看关联角色及权限；需要调整授权请到角色管理。</p><a-alert v-if="roleError" type="warning" :message="roleError" show-icon/><div v-else class="menu-table-scroll"><table class="menu-special-table"><thead><tr><th>角色名称</th><th>角色编码</th><th>普通权限</th><th>特殊权限</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="role in roles" :key="role.id"><td>{{role.roleName}}</td><td>{{role.roleCode}}</td><td><a-tag :color="level(role)==='管理'?'green':'blue'">{{level(role)}}</a-tag></td><td><a-tag v-for="name in specialRole(role)" :key="name" color="blue">{{name}}</a-tag><span v-if="!specialRole(role).length" class="muted">—</span></td><td><span :class="role.status==='ACTIVE'?'menu-green':'menu-gray'">{{role.status==='ACTIVE'?'● 启用':'● 停用'}}</span></td><td><a-button type="link" @click="roleInfo=role">查看授权</a-button></td></tr></tbody></table><a-empty v-if="!roles.length" description="当前菜单无关联角色"/></div></template>
<div class="menu-bottom-actions"><a-button aria-label="取消" :disabled="busy" @click="back">{{readonly?'返回':'取消'}}</a-button><a-button v-if="!readonly" :disabled="!canEdit" @click="restore">恢复上次保存</a-button><a-button v-if="!readonly" type="primary" :disabled="!canEdit" :loading="busy" @click="save">保存配置</a-button></div></section></a-spin>
<a-modal v-model:open="modal" :title="mode==='new'?'新增特殊权限':mode==='edit'?'编辑特殊权限':'关联已有权限'" centered width="560px" :ok-text="mode==='link'?'关联':'确定'" @ok="submit"><a-alert v-if="formError" type="error" :message="formError" show-icon/><div class="menu-modal-fields"><label v-if="mode==='link'" class="menu-pair"><span class="form-field-label">已有权限</span><a-select v-model:value="form.code" aria-label="已有权限" :options="available" show-search option-filter-prop="label"/></label><template v-else><label class="menu-pair"><span class="form-field-label">权限名称 <em>*</em></span><a-input aria-label="权限名称" v-model:value="form.name" :maxlength="128"/></label><label class="menu-pair"><span class="form-field-label">权限编码 <em>*</em></span><a-input aria-label="权限编码" v-model:value="form.code" :disabled="mode==='edit'" :maxlength="160"/></label><label class="menu-pair"><span class="form-field-label">权限说明</span><a-input aria-label="权限说明" v-model:value="form.description" :maxlength="512"/></label><div class="menu-pair"><span>状态</span><a-radio-group v-model:value="form.status"><a-radio value="ACTIVE">启用</a-radio><a-radio value="INACTIVE">停用</a-radio></a-radio-group></div></template></div></a-modal>
<a-modal :open="!!roleInfo" title="角色授权" :footer="null" @cancel="roleInfo=null"><template v-if="roleInfo"><p>{{roleInfo.roleName}}（{{roleInfo.roleCode}}）</p><p>普通权限：{{level(roleInfo)}}</p><p>特殊权限：{{specialRole(roleInfo).join('、')||'无'}}</p><a-button @click="router.push(`/admin/roles/${roleInfo.id}`)">查看角色详情</a-button></template></a-modal>
</main></template>
